/* The intake is universal (medical history, medications, allergies, pregnancy, procedures, consents) plus one section that belongs to the vertical. */
function intakeTemplate(T) {
  const C = 'Cancer (current or past)';
  return { id: 'intake', name: 'New Client Intake & Health History', kind: 'intake', estMinutes: 6, fields: [
    { type: 'section', label: 'About you', desc: 'Who to call and how you found us.' },
    { id: 'emergency_name', label: 'Emergency contact name', type: 'text', placeholder: 'Full name' },
    { id: 'emergency_phone', label: 'Emergency contact phone', type: 'phone', placeholder: '(225) 555-0100' },
    { id: 'occupation', label: 'Occupation', type: 'text', placeholder: T.intake.occupationHint || 'Helps us understand your day-to-day exposure' },
    { id: 'referral', label: 'How did you hear about us?', type: 'choice', options: ['Instagram', 'TikTok', 'Google', 'Friend or family', 'Walked by', 'Website', 'Other'] },

    { type: 'section', label: 'Medical history', desc: 'Everything here stays in your private file. It decides which services are safe for you.' },
    { id: 'conditions', label: 'Do you have, or have you had, any of the following?', type: 'multi', options: [C, 'Diabetes', 'Autoimmune disorder (lupus, RA, MS…)', 'Thyroid condition', 'Heart condition or high blood pressure', 'Pacemaker or metal implants', 'Epilepsy or seizures', 'Bleeding or clotting disorder', 'Blood clots or DVT', 'Hepatitis or HIV', 'Cold sores (herpes simplex)', 'Eczema, psoriasis or dermatitis', 'Rosacea', 'Keloid or raised scarring', 'Neuromuscular disorder (MG, ALS…)', 'Recent surgery (last 6 months)', 'Asthma', 'None of these'] },
    { id: 'cancer_type', label: 'Type of cancer', type: 'text', placeholder: 'e.g. breast, skin, lymphoma', showIf: { field: 'conditions', includes: C } },
    { id: 'cancer_status', label: 'Where are you in treatment?', type: 'choice', options: ['In treatment now', 'Finished within the last 12 months', 'In remission over a year', 'Monitoring only'], showIf: { field: 'conditions', includes: C } },
    { id: 'cancer_tx', label: 'Treatments received or planned', type: 'multi', options: ['Chemotherapy', 'Radiation', 'Surgery', 'Immunotherapy', 'Hormone therapy', 'Targeted therapy', 'None yet'], showIf: { field: 'conditions', includes: C } },
    { id: 'cancer_radiation_area', label: 'Area treated with radiation', type: 'text', placeholder: 'e.g. left chest, neck', showIf: { field: 'cancer_tx', includes: 'Radiation' } },
    { id: 'cancer_lymph', label: 'Lymph nodes removed or lymphedema risk?', type: 'choice', options: ['No', 'Left side', 'Right side', 'Both sides', 'Not sure'], showIf: { field: 'conditions', includes: C } },
    { id: 'cancer_port', label: 'Port or PICC line currently in place?', type: 'yesno', showIf: { field: 'conditions', includes: C } },
    { id: 'cancer_effects', label: 'Current side effects', type: 'multi', options: ['Skin sensitivity or dryness', 'Numbness or tingling (neuropathy)', 'Fatigue', 'Nausea', 'Low immunity or low platelets', 'Hair loss', 'Mouth sores', 'None right now'], showIf: { field: 'conditions', includes: C } },
    { id: 'cancer_clearance', label: 'Physician clearance for these services', type: 'choice', options: ['Yes, letter on file', 'Yes, I will bring it', 'Not yet'], hint: 'We ask every oncology client for written clearance before the first service.', showIf: { field: 'conditions', includes: C } },
    { id: 'cancer_physician', label: 'Treating physician and phone', type: 'text', placeholder: 'Dr. name · (225) 555-0100', showIf: { field: 'conditions', includes: C } },
    { id: 'conditions_detail', label: 'Anything else about your health we should know?', type: 'textarea', placeholder: 'Surgeries, implants, recent illness, anything that affects your comfort' },
    { id: 'meds', label: 'Are you using any of these?', type: 'multi', options: ['Accutane / isotretinoin (last 12 months)', 'Retinoids (tretinoin, retinol, adapalene)', 'Antibiotics', 'Blood thinners (aspirin, warfarin, Eliquis…)', 'Steroids (oral or topical)', 'Hormone therapy or birth control', 'Immunosuppressants', 'Thyroid medication', 'Hydroquinone or other prescription creams', 'None of these'] },
    { id: 'meds_list', label: 'List all current medications and supplements', type: 'textarea', placeholder: 'Name and dose, or “none”' },
    { id: 'allergies', label: 'Allergies or sensitivities', type: 'multi', options: ['Latex', 'Nuts', 'Fragrance', 'Shellfish', 'Aspirin or salicylates', 'Sulfa drugs', 'Adhesives (lash glue, tape)', 'Hair dye (PPD)', 'Acrylates (gel or acrylic nails)', 'Essential oils', 'Lidocaine or numbing creams', 'Seasonal allergies', 'None known'] },
    { id: 'allergies_other', label: 'Other allergies and what happens', type: 'text', placeholder: 'e.g. penicillin — hives; bee stings — EpiPen' },
    { id: 'pregnant', label: 'Pregnancy', type: 'choice', options: ['Not applicable', 'Pregnant', 'Trying to conceive', 'Nursing'] },
    { id: 'trimester', label: 'Which trimester?', type: 'choice', options: ['First', 'Second', 'Third'], showIf: { field: 'pregnant', equals: 'Pregnant' } },

    { type: 'section', label: 'Recent treatments', desc: 'Anything in the last 4 weeks.' },
    { id: 'procedures', label: 'Have you had any of these recently?', type: 'multi', options: ['Botox or fillers', 'Laser or IPL', 'Chemical peel', 'Microneedling', 'Waxing or threading', 'Facial or body surgery', 'Tattoo or permanent makeup', 'Sunburn or tanning bed', 'None of these'] },
    { id: 'procedures_date', label: 'Date of the most recent one', type: 'date', showIf: { field: 'procedures', notIncludes: 'None of these', nonEmpty: true } },

    { type: 'section', label: T.intake.section.label, desc: T.intake.section.desc },
    ...T.intake.section.fields,

    { type: 'section', label: 'Home care', desc: 'What you use now.' },
    { id: 'routine', label: T.intake.routineLabel || 'Products you use regularly', type: 'multi', options: T.intake.routineOptions },
    { id: 'products', label: 'Brands and products', type: 'textarea', placeholder: 'Whatever is on your counter' },

    { type: 'section', label: 'Goals & preferences' },
    { id: 'goals', label: 'What would make this visit a win for you?', type: 'textarea' },
    { id: 'pressure', label: T.intake.pressureLabel || 'Pressure during massage or treatment', type: 'choice', options: ['Light', 'Medium', 'Firm'] },
    { id: 'scent', label: 'Sensitive to scents or essential oils?', type: 'yesno' },
    { id: 'chat', label: 'During your service', type: 'choice', options: ['Chat with me', 'Quiet, please', 'Either'] },
    { id: 'photos', label: 'Before & after photos', type: 'choice', options: ['Yes, for my file only', 'Yes, and you may share them without my name', 'No photos'] },

    { type: 'section', label: 'Consent' },
    { id: 'under18', label: 'Are you under 18?', type: 'yesno' },
    { id: 'guardian', label: 'Parent or guardian name', type: 'text', showIf: { field: 'under18', equals: 'Yes' } },
    { id: 'accurate', label: 'The information above is accurate and complete.', type: 'agree' },
    { id: 'notify', label: 'I will tell my provider about changes to my health, medications or pregnancy before each visit.', type: 'agree' },
    { id: 'policy', label: 'I understand the 24-hour cancellation policy and consent to service.', type: 'agree' },
    { id: 'sig', label: 'Signature', type: 'signature' },
  ] };
}

